input.contents:
$path = 'g:\0.DỰ ÁN\WWEB-TAM-DUC\SQL\INFO_AboutPageContent -data.sql'
$raw = Get-Content -LiteralPath $path -Raw
$data = $raw | ConvertFrom-Json
Write-Output ("TOTAL_ROWS=" + $data.Count)
Write-Output '--- SECTIONS ---'
$data | Group-Object sectioncode | Sort-Object Name | ForEach-Object { Write-Output ($_.Name + '=' + $_.Count) }
Write-Output '--- TYPES ---'
$data | Group-Object contenttype | Sort-Object Name | ForEach-Object { Write-Output ($_.Name + '=' + $_.Count) }
Write-Output '--- PAGECODES ---'
$data | Group-Object pagecode | ForEach-Object { Write-Output ($_.Name + '=' + $_.Count) }
Write-Output '--- IMAGE ROWS ---'
$data | Where-Object { $_.contenttype -eq 'image' } | ForEach-Object { Write-Output ($_.contentcode + '|' + $_.imageurl) }
Write-Output '--- VALUES ---'
$data | Where-Object { $_.sectioncode -eq 'values' } | ForEach-Object { Write-Output $_.contentcode }
Write-Output '--- LEADER/CEO IMAGE ---'
$data | Where-Object { $_.contentcode -match 'leader.*image|ceo_image' } | ForEach-Object { Write-Output ($_.contentcode + '|' + $_.imageurl) }
Write-Output '--- CONTENTCODES ---'
$data | ForEach-Object { Write-Output $_.contentcode }

var fs = require("fs");
var path = require("path");

var root = path.resolve(__dirname, "..");
var dataPath = path.join(__dirname, "INFO_AboutPageContent -data.sql");
var ascxPath = path.join(root, "HOS", "Controls", "Information", "About", "SectionAboutUs.ascx");
var cssPath = path.join(root, "HOS", "assets", "cus", "css", "about.css");
var outPath = path.join(__dirname, "CMS_LandingPage_AboutUs.sql");

function readUtf8(p) {
  var buf = fs.readFileSync(p);
  if (buf.length >= 3 && buf[0] === 0xEF && buf[1] === 0xBB && buf[2] === 0xBF) {
    return buf.slice(3).toString("utf8");
  }
  var s = buf.toString("utf8");
  if (s.charCodeAt(0) === 0xFEFF) s = s.slice(1);
  return s;
}

function sqlN(str) {
  if (str == null) return "NULL";
  return "N'" + String(str).replace(/'/g, "''") + "'";
}

function formatNum(val) {
  if (val == null || val === "") return "";
  var n = Number(val);
  if (!isFinite(n)) return String(val);
  if (n === Math.trunc(n)) return String(Math.trunc(n));
  return String(n);
}

var rows = JSON.parse(readUtf8(dataPath));
var map = {};
for (var i = 0; i < rows.length; i++) {
  var row = rows[i];
  var code = (row.contentcode || row.ContentCode || "").toString();
  if (!code) continue;
  map[code.toLowerCase()] = row;
}

function getRow(code) {
  return map[String(code).toLowerCase()] || null;
}

function C(code, lang) {
  var r = getRow(code);
  if (!r) return "";
  var v = lang === "en" ? (r.contenten || r.ContentEn) : (r.contentvi || r.ContentVi);
  return v == null ? "" : String(v);
}

function Img(code) {
  var r = getRow(code);
  if (!r) return "";
  var v = r.imageurl || r.ImageUrl;
  return v == null ? "" : String(v);
}

function Link(code) {
  var r = getRow(code);
  if (!r) return "";
  var v = r.linkurl || r.LinkUrl;
  return v == null ? "" : String(v);
}

function Num(code) {
  var r = getRow(code);
  if (!r) return "";
  return formatNum(r.numbervalue != null ? r.numbervalue : r.NumberValue);
}

function Suffix(code) {
  var r = getRow(code);
  if (!r) return "";
  var v = r.numbersuffix || r.NumberSuffix;
  return v == null ? "" : String(v);
}

var ascx = readUtf8(ascxPath);
var htmlStart = ascx.indexOf("<!-- Hero -->");
var htmlEnd = ascx.indexOf("<!-- Newsletter -->");
if (htmlStart < 0 || htmlEnd < 0) {
  throw new Error("Cannot find About markup bounds");
}
var markup = ascx.substring(htmlStart, htmlEnd);

function fill(markupHtml, lang) {
  var html = markupHtml;
  html = html.replace(/<%= C\("([^"]+)"\) %>/g, function (_, code) {
    return C(code, lang);
  });
  html = html.replace(/<%= Img\("([^"]+)"\) %>/g, function (_, code) {
    return Img(code);
  });
  html = html.replace(/<%= Link\("([^"]+)"\) %>/g, function (_, code) {
    return Link(code);
  });
  html = html.replace(/<%= Num\("([^"]+)"\) %>/g, function (_, code) {
    return Num(code);
  });
  html = html.replace(/<%= Suffix\("([^"]+)"\) %>/g, function (_, code) {
    return Suffix(code);
  });
  if (/<%/.test(html)) {
    throw new Error("Unresolved server expression remains");
  }
  return '<div class="about-page">\n' + html.trim() + "\n</div>";
}

var htmlVi = fill(markup, "vi");
var htmlEn = fill(markup, "en");

var css = readUtf8(cssPath);
css = css.replace(/:root\s*\{/, ".about-page {");
css = css.replace(/\*\s*\{\s*margin:\s*0;\s*padding:\s*0;\s*box-sizing:\s*border-box;\s*\}/,
  ".about-page *, .about-page *::before, .about-page *::after { box-sizing: border-box; }");
css = css.replace(/\bbody\s*\{/, ".about-page {");
css = css.replace(/\.container\b/g, ".about-page .container");
css = css.replace(/img\.lazy-fade/g, ".about-page img.lazy-fade");
css = css.replace(/\/\* Smooth scroll[\s\S]*$/m, "");
css = css.replace(/^html\s*\{[\s\S]*?\}\s*$/m, "");
css = "/* ABOUT PAGE CSS - scoped under .about-page - generated for CMS_LandingPage */\n" + css.trim() + "\n";

var missingVi = [];
markup.replace(/<%= C\("([^"]+)"\) %>/g, function (_, code) {
  if (!getRow(code)) missingVi.push(code);
});

var header = [
  "USE [thienhaso_WEB_His_TimTamDuc_2025]",
  "GO",
  "",
  "/*",
  "  INSERT/UPDATE page About vao CMS_LandingPage",
  "  Slug VI : about-us",
  "  Slug EN : about-us-en",
  "  HtmlBody = markup SectionAboutUs (khong Master, khong JS)",
  "  CssText  = about.css da scope .about-page",
  "  ProjectJson = {}  (GrapesJS se load tu HtmlBody lan dau)",
  "  Khong xoa INFO_AboutPageContent",
  "  Khong sua cac landing page khac",
  "*/",
  ""
].join("\r\n");

function upsertBlock(slug, pageName, title, html, cssText, keyword) {
  return [
    "IF EXISTS (SELECT 1 FROM [dbo].[CMS_LandingPage] WHERE [Slug] = N'" + slug + "')",
    "BEGIN",
    "    UPDATE [dbo].[CMS_LandingPage]",
    "    SET",
    "        [PageName] = " + sqlN(pageName) + ",",
    "        [Title] = " + sqlN(title) + ",",
    "        [Description] = N'About page full HTML'",
    "        ,[Keyword] = " + sqlN(keyword) + ",",
    "        [CssText] = " + sqlN(cssText) + ",",
    "        [HtmlBody] = " + sqlN(html) + ",",
    "        [ProjectJson] = N'{}',",
    "        [MetaDescription] = " + sqlN(title) + ",",
    "        [IsActive] = 1,",
    "        [SortOrder] = 10,",
    "        [UpdatedDate] = GETDATE(),",
    "        [UpdatedUser] = N'seed-about'",
    "    WHERE",
    "        [Slug] = N'" + slug + "';",
    "END",
    "ELSE",
    "BEGIN",
    "    INSERT INTO [dbo].[CMS_LandingPage]",
    "    (",
    "        [Slug],",
    "        [Title],",
    "        [Description],",
    "        [Keyword],",
    "        [CssText],",
    "        [HtmlBody],",
    "        [IsActive],",
    "        [SortOrder],",
    "        [CreatedDate],",
    "        [CreatedUser],",
    "        [UpdatedDate],",
    "        [UpdatedUser],",
    "        [ProjectJson],",
    "        [PageName],",
    "        [MetaDescription]",
    "    )",
    "    VALUES",
    "    (",
    "        N'" + slug + "',",
    "        " + sqlN(title) + ",",
    "        N'About page full HTML',",
    "        " + sqlN(keyword) + ",",
    "        " + sqlN(cssText) + ",",
    "        " + sqlN(html) + ",",
    "        1,",
    "        10,",
    "        GETDATE(),",
    "        N'seed-about',",
    "        GETDATE(),",
    "        N'seed-about',",
    "        N'{}',",
    "        " + sqlN(pageName) + ",",
    "        " + sqlN(title),
    "    );",
    "END",
    "GO",
    ""
  ].join("\r\n");
}

var sql = header
  + upsertBlock("about-us", "AboutUs", "Về Tâm Đức", htmlVi, css, "vi")
  + upsertBlock("about-us-en", "AboutUs-EN", "About Tam Duc", htmlEn, css, "en");

fs.writeFileSync(outPath, sql, "utf8");

console.log("Wrote", outPath);
console.log("Rows seed", rows.length);
console.log("HTML VI chars", htmlVi.length);
console.log("HTML EN chars", htmlEn.length);
console.log("CSS chars", css.length);
console.log("SQL chars", sql.length);
console.log("Missing ContentCodes", missingVi.length ? missingVi.join(",") : "(none)");

