aboutCss = data.CssText || '';
var html = data.HtmlBody || '';
var chk = document.getElementById('chkPublish');
if (chk) chk.checked = data.IsActive !== false;
if (!html || (data.UpdatedUser && String(data.UpdatedUser).toLowerCase() === 'seed-about')) {
    aboutWriteCanvas(aboutCss, html, false);
    aboutImport();
